-- Replace robot avatar icons with football-themed ones (brand rebrand).
-- Run once in the Supabase SQL Editor. Idempotent -- safe to re-run.
--
-- The original seed (combined_migrations.sql) used external Dicebear
-- "bottts" robot avatars. This swaps them for 8 self-contained SVG data
-- URIs (football, helmet, flag, whistle, goalpost, cleat, playbook,
-- trophy) in the new navy/turf/chalk palette -- no external image host,
-- so api.dicebear.com can also be dropped from the CSP img-src allowlist.

-- Idempotency: clear out any icons from a prior run of this file before
-- re-inserting, so re-running never duplicates the set.
DELETE FROM avatar_icons WHERE name IN
  ('Football', 'Helmet', 'Flag', 'Whistle', 'Goalpost', 'Cleat', 'Playbook', 'Trophy');

