-- Point any user currently on an old (bot) icon to the new default,
-- then remove the old rows -- avatar_icon_id has no ON DELETE action,
-- so users must be repointed before the referenced rows are deleted.
DO $$
DECLARE
  new_default_id uuid;
BEGIN
  SELECT id INTO new_default_id FROM avatar_icons WHERE name = 'Football' LIMIT 1;

  UPDATE user_reputation
  SET avatar_icon_id = new_default_id
  WHERE avatar_icon_id IN (SELECT id FROM avatar_icons WHERE icon_url LIKE '%dicebear%');

  DELETE FROM avatar_icons WHERE icon_url LIKE '%dicebear%';
END $$;
